fn solve(n: i8) -> Vec<i8> {
    match n % 3 {
        0 => {
            // n is divisible by 3
            let a = n / 3;
            vec![a, 0, 0]
        }
        1 => {
            // n ≡ 1 (mod 3)
            if n < 7 {
                vec![-1]
            } else {
                let a = (n - 7) / 3;
                vec![a, 0, 1]
            }
        }
        2 => {
            // n ≡ 2 (mod 3)
            if n < 5 {
                vec![-1]
            } else {
                let a = (n - 5) / 3;
                vec![a, 1, 0]
            }
        }
        _ => unreachable!(), // n % 3 is always 0, 1, or 2 for positive n
    }
}

